import fs from 'node:fs'
import path from 'node:path'
import assert from 'node:assert/strict'
import {fileURLToPath} from 'node:url'
const root=fileURLToPath(new URL('../',import.meta.url))
const repoRoot=path.resolve(root,'..')
const read=p=>fs.readFileSync(path.join(repoRoot,p),'utf8')
// Blog HTML is generated by postbuild; source is a shell, not a byte-for-byte mirror.
const renderedBlog=path.join(root,'dist/fa/blog')
for(const name of ['reader.css','reader.js']){
 assert.equal(read('site/public/fa/blog/'+name),fs.readFileSync(path.join(renderedBlog,name),'utf8'),'Blog build asset mismatch: '+name)
}
const generatedIndex=fs.readFileSync(path.join(renderedBlog,'index.html'),'utf8')
assert.ok(generatedIndex.includes('href="https://ialirezaaa.github.io/fa/blog/"'))
assert.ok(generatedIndex.includes('/fa/blog/categories/') && generatedIndex.includes('/fa/blog/tags/'))
assert.equal(read('site/public/fa/garden/index.html'),read('site/dist/fa/garden/index.html'),'Garden build shell mismatch')
const shell=read('site/public/fa/blog/index.html')
for(const phrase of ['id="font"','Vazirmatn','read-progress','/fa/garden/'])assert.ok(shell.includes(phrase),'Missing blog enhancement: '+phrase)
const graph=JSON.parse(read('site/dist/fa/garden/graph.json'))
assert.ok(graph.nodes.length>=5)
const ids=new Set(graph.nodes.map(n=>n.id));assert.equal(ids.size,graph.nodes.length)
assert.ok(graph.nodes.some(n=>n.url==='/fa/blog/diffusion-from-noise/'))
for(const e of graph.edges){assert.ok(ids.has(e.source)&&ids.has(e.target),'Dangling graph edge')}
const notes=fs.readdirSync(path.join(root,'garden/notes')).filter(x=>x.endsWith('.md'))
for(const note of notes){const text=read('site/garden/notes/'+note);assert.match(text,/dg-publish: true/);assert.match(text,/public: true/)}
console.log('PASS: generated blog and reader assets, built Garden graph, font controls, note graph links, approved Markdown')
